// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1000);

        // Call Initialized first
        vm.prank(alice);
        c.Initialized();

        // Try SetMinSum(100) — in reference reverts (because initialized), in bug succeeds
        vm.prank(alice);
        bool ok;
        try c.SetMinSum(100) {
            ok = true;
        } catch {
            ok = false;
        }
        // We don't assert on ok; just proceed

        // Deposit 50 wei
        vm.prank(alice);
        c.Deposit{value: 50}();

        // Fund contract with some ether so Collect can send
        vm.deal(address(c), 1000);

        // Collect 30 wei
        vm.prank(alice);
        c.Collect(30);

        // In reference: SetMinSum reverted, MinSum=0, Collect condition passes, balance = 50-30 = 20
        // In bug: SetMinSum succeeded, MinSum=100, condition fails, balance stays 50
        assertEq(c.balances(alice), 20);
    }
}

