        // Call Initialized to set intitalized = true
        c.Initialized();
        // Then call SetMinSum – should revert in reference (since already initialized),
        // but in buggy version it uses !intitalized, so it will succeed.
        // Use try/catch to observe revert boolean.
        bool ok;
        try c.SetMinSum(100) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference version, ok should be false (revert). In buggy, ok should be true.
        // We assert that ok is false, which will pass on reference and fail on buggy.
        assertTrue(!ok);
    }
}

