pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 10 ether);

        // Set MinSum to 5 (reference sets it to 5, buggy sets it to 0)
        vm.prank(user);
        c.SetMinSum(5);

        // Initialize (locks MinSum)
        vm.prank(user);
        c.Initialized();

        // Deposit 3 wei
        vm.prank(user);
        c.Deposit{value: 3}();

        // Try Collect 1 wei — in reference, condition fails (3 >= 5 false) so no change
        // In buggy, condition passes (3 >= 0 true) and 3 >= 1, so sends 1 wei, balance becomes 2
        bool ok;
        try c.Collect(1) { ok = true; } catch { ok = false; }
        assertTrue(ok);

        // Now check balance: reference has 3, buggy has 2
        assertEq(c.balances(user), 3);
    }
}

