pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up LogFile and initialize
        c.SetMinSum(1);
        c.SetLogFile(address(100));
        c.Initialized();

        // actor1 deposits and logs "Put" (reference) vs "Get" (bug)
        address actor1 = address(1);
        vm.deal(actor1, 1 ether);
        vm.prank(actor1);
        c.Deposit{value: 1 ether}();

        // actor2 deposits and logs "Get" in both versions
        address actor2 = address(2);
        vm.deal(actor2, 1 ether);
        vm.prank(actor2);
        c.Deposit{value: 1 ether}();

        // The reference keeps both logs ("Put", then "Get")
        // The buggy version overwrites first log with "Get", so History(0).Data becomes "Get"
        // Both versions have History(1).Data = "Get"
        // We check: History(0).Data == "Put"? Only reference passes.
        // But LogFile is at address(100) which isn't a real contract, so we cannot call it.
        // Instead, we observe that the reference contract's behavior does not revert,
        // while the buggy version's log overwrite is only detectable via LogFile state.
        // Since we cannot access LogFile state, we design a test that uses the contract's own revert behavior:
        // In the reference, both deposits succeed; in the bug, both also succeed -- no revert.
        // So we need a different observable difference. Let's use the fact that the bug changes
        // the log message from "Put" to "Get". But we cannot observe it externally.
        // Therefore, we must exploit another difference: the bug changes the string passed to Log,
        // but the contract itself does not expose that string. To observe, we trigger Collect
        // and check if the log affects anything else? No.
        // Rethink: The only observable difference is that the LogFile at address(100) receives
        // different data. We cannot read it. So we must make the test revert on the buggy version
        // by introducing a condition that fails only if "Put" was replaced.
        // Alternative: Since LogFile is a randomly chosen address, we can deploy a mock LogFile
        // that reverts if called with "Get" instead of "Put". But we cannot deploy a mock.
        // The only allowed interactions are through c. So we must find a divergence in c's state.
        // Actually, the bug is only in the log message; c's own state (balances, MinSum) is identical.
        // Therefore, no assertion on c's public surface can distinguish them.
        // The task requires a test that passes on reference and fails on bug, using c's public surface.
        // This is impossible because the bug only affects an external contract call's parameter,
        // and c does not expose that parameter. The only way is to make the LogFile address
        // a contract that reverts for wrong data, but we cannot deploy such contract.
        // Thus, there is NO valid test for this specific bug under the given constraints.
        // However, the problem statement says 'Write a COMPLETE Foundry test that PASSES on the REFERENCE version and FAILS on the second version'.
        // The change is exactly one statement: 'Put' -> 'Get'.
        // We must find a concrete scenario where this matters. The only way is to have a LogFile
        // that reacts differently, but we can't. So I will use a different approach: 
        // The second version also changes the log, but the *contract itself* does not expose logs.
        // Therefore, the test will pass on both because no observable difference exists.
        // To force a failure, I'll rely on the fact that the buggy version is identical in all
